            width: "100%",
            height: "100%",
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
            transformOrigin: "center center",
            transition: isDragging ? "none" : "transform 0.08s ease-out",
          }}
          preserveAspectRatio="xMidYMid meet"
        >
          <image
            href="/camping-map-v2.svg"
            x={MAP_VIEWBOX.x}
            y={MAP_VIEWBOX.y}
            width={MAP_VIEWBOX.width}
            height={MAP_VIEWBOX.height}
            preserveAspectRatio="xMidYMid meet"
          />

          {mapPlaces
            .filter((place) => place.points.trim() !== "")
            .map((place) => {
              const center = getCenter(place.points);
              const placeData = places.find((p) => p.id === place.id);
              const placeStatus = getStatusForPlace(place.id, placeStatuses);
              const isSelected = selectedPlaceId === place.id;
              const isHovered = hoveredPlaceId === place.id;
              const visiblePlaceName = placeData?.name ?? place.label;
              const isAvailableForSearch = availablePlaceIds.includes(place.id);

              const isBlockedByStatus =
                placeStatus?.status === "gray" ||
                placeStatus?.status === "blocked";

              const isUnavailableForSearch =
                availabilityMode &&
                (isBlockedByStatus || !isAvailableForSearch);
              const fillColor = isUnavailableForSearch
                ? "rgba(31,41,55,0.45)"
                : getPlaceFillColor(placeStatus, isHovered, isSelected);

              const strokeColor = isUnavailableForSearch
                ? "#1f2937"
                : getPlaceStrokeColor(placeStatus, isSelected, isHovered);

              const strokeWidth = isSelected ? 18 : isHovered ? 15 : 12;
              return (
                  <g key={place.id}>
                    <polygon
                        points={place.points}
                        fill={fillColor}
                        stroke={strokeColor}
                        strokeWidth={strokeWidth}
                        onClick={(e) => {
                          if (editMode) return;
                          if (isUnavailableForSearch) return;

                          e.stopPropagation();
                          onSelectPlace(place.id);
                        }}
                        onDoubleClick={(e) => {
                          if (editMode) return;
                          if (isUnavailableForSearch) return;

                          e.stopPropagation();
                          zoomToPlace(place.id);
                        }}
                        onMouseEnter={() => {
                          if (!editMode && !isUnavailableForSearch) setHoveredPlaceId(place.id);
                        }}
                        onMouseLeave={() => {
                          if (!editMode) setHoveredPlaceId(null);
                        }}
                        style={{
                          cursor: editMode
                              ? "crosshair"
                              : isUnavailableForSearch
                                  ? "not-allowed"
                                  : "pointer",
                          transition:
                              "fill 0.14s ease, stroke 0.14s ease, stroke-width 0.14s ease, opacity 0.14s ease",
                          filter: isSelected
                              ? "drop-shadow(0 0 10px rgba(37,99,235,0.35))"
                              : isHovered
                                  ? "drop-shadow(0 0 8px rgba(0,0,0,0.12))"
                                  : "none",
                        }}
                    />

                    <text
                        x={center.x}
                        y={center.y}
                        textAnchor="middle"
                        dominantBaseline="central"
                        fontSize="80"
                        fill="#111827"
                        style={{
                          pointerEvents: "none",
                          userSelect: "none",
                          fontWeight: isSelected ? 800 : 700,
                        }}
                    >
                      {visiblePlaceName}
                    </text>
                  </g>
              );
            })}

          {editMode && polygonPoints.length > 0 && (
              <>
                {polygonPoints.map((point, index) => (
                    <circle
                        key={`${point.x}-${point.y}-${index}`}
                        cx={point.x}
                        cy={point.y}
                        r="18"
                        fill="#2563eb"
                        stroke="white"
                        strokeWidth="6"
                    />
                ))}

                {polygonPoints.length >= 2 && (
                    <polyline
                        points={polygonString}
                        fill="none"
                        stroke="#2563eb"
                        strokeWidth="18"
                        strokeDasharray="40 25"
                    />
                )}

                {polygonPoints.length === 4 && (
                    <polygon
                        points={polygonString}
                        fill="rgba(37, 99, 235, 0.20)"
                        stroke="#2563eb"
                        strokeWidth="18"
                />
              )}
            </>
          )}
        </svg>

{!editMode && hoveredPlace && (
  <div style={tooltipCardStyle}>
    <div style={tooltipTitleStyle}>Platz {hoveredPlace.name}</div>

    <div style={tooltipMetaRowStyle}>
      <span style={tooltipBadgeStyle}>
        {hoveredPlace.type || "Stellplatz"}
      </span>
      <span style={tooltipBadgeStyle}>
        Kapazität {hoveredPlace.capacity}
      </span>
    </div>

    {hoveredPlaceBookings.length === 0 ? (
      <div style={tooltipTextMutedStyle}>Keine Buchungen vorhanden.</div>
    ) : (
      <div style={tooltipBookingsStyle}>
        <div style={tooltipBookingsTitleStyle}>Buchungen</div>

        {hoveredPlaceBookings.slice(0, 4).map((booking) => (
          <div key={booking.id} style={tooltipBookingItemStyle}>
            <strong>{booking.guest_name}</strong>
            <span>
              {formatDate(booking.start_date)} – {formatDate(booking.end_date)}
            </span>

            {booking.status === "noshow" && (
              <span style={tooltipNoShowStyle}>Nicht erschienen</span>
            )}
          </div>
        ))}

        {hoveredPlaceBookings.length > 4 && (
          <div style={tooltipMoreStyle}>
            + {hoveredPlaceBookings.length - 4} weitere Buchung(en)
          </div>
        )}
      </div>
    )}
  </div>
)}
</div>

      <div
        style={{
          ...legendStyle,
          gap: isMobile ? "0.5rem" : legendStyle.gap,
          padding: isMobile ? "0.7rem" : legendStyle.padding,
        }}
      >
        <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(34,197,94,0.55)",
          borderColor: "#16a34a",
        }}
    />
          Frei
        </div>

        <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(234,179,8,0.60)",
          borderColor: "#eab308",
        }}
    />
          Teilweise belegt
        </div>

        <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(220,38,38,0.60)",
          borderColor: "#dc2626",
        }}
    />
          Voll belegt
        </div>

        <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(107,114,128,0.50)",
          borderColor: "#6b7280",
        }}
    />
            Dauercamper
          </div>

          <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(124,58,237,0.45)",
          borderColor: "#7c3aed",
        }}
    />
            Gesperrt
          </div>

          <div style={legendItemStyle}>
    <span
        style={{
          ...legendDotStyle,
          backgroundColor: "rgba(37,99,235,0.26)",
          borderColor: "#2563eb",
        }}
    />
            Ausgewählt
          </div>
      </div>

      {isDeveloper && (
          <div style={developerPanelStyle}>
            <div style={developerPanelHeaderStyle}>
              <div>
                <h3 style={developerPanelTitleStyle}>Polygon-Werkzeug</h3>
                <p style={developerPanelTextStyle}>
          Bearbeitungsmodus aktivieren und 4 Ecken auf der Karte anklicken.
        </p>
      </div>

      <div style={developerBadgeStyle}>
        {polygonPoints.length} / 4 Punkte
      </div>
    </div>

    <div style={developerCodeBoxStyle}>
      {polygonString || "Noch keine Punkte gesetzt."}
    </div>

    {polygonPoints.length === 4 && (
      <div style={developerResultBoxStyle}>
        <strong>Fertiges Polygon:</strong>
        <pre style={developerPreStyle}>
{`<polygon
  points="${polygonString}"
  fill="rgba(34,197,94,0.25)"
  stroke="#16a34a"
  onClick={() => onSelectPlace(PLATZ_ID)}
/>`}
        </pre>
      </div>
    )}
  </div>
)}
</div>
  );
}

