                    {place.capacity}
                  </div>
                </div>

                <div style={placeBottomRowStyle}>
                  <span
                    style={{
                      ...statusDotStyle,
                      backgroundColor: getStatusColor(status),
                    }}
                  />
                  <span
                    style={{
                      ...placeMetaStyle,
                      ...(isSelected ? selectedPlaceMetaStyle : {}),
                    }}
                  >
                    {getStatusText(place, status)}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

